def generate(lang):
 en=lang=='en'; ix=int(en); base='en/' if en else ''; other='' if en else 'en/'
 def t(es,eng):return tr(es,eng,lang)
 routes={'home':'','work':'trabajo/','services':'capacidades/','studio':'estudio/','contact':'contacto/','privacy':'privacidad/'}
 navnames={'work':t('Trabajo','Work'),'services':t('Capacidades','Capabilities'),'studio':t('Estudio','Studio')}
 def pagepath(key):return base+routes.get(key,'casos/'+key+'/')+'index.html'
 def relative(target,current):return posixpath.relpath(target,posixpath.dirname(current) or '.')
 def render(key,title,body,description):
  current=pagepath(key)
  def url(k):return relative(pagepath(k),current)
  def asset(f):return relative(f,current)
  # Internal template placeholders are resolved only after a page is complete.
  for k in list(routes)+[c['slug'] for c in cases]:body=body.replace('@'+k+'@',url(k))
  body=body.replace('@assets@',asset('assets'))
  nav=''.join(f'<a href="{url(k)}"'+(' aria-current="page"' if k==key else '')+f'>{v}</a>' for k,v in navnames.items())
  langlink=relative(other+routes.get(key,'casos/'+key+'/')+'index.html',current)
  cta='' if key in ['contact','privacy'] else f'''<section class="cta wrap"><div class="cta-top eyebrow"><span>{t('La próxima historia','The next story')}</span><span>Backstory Contenidos</span></div><a class="cta-title" href="{url('contact')}"><span>{t('¿Hacemos<br>equipo?','Let’s make<br>it happen.')}</span><span class="arrow" aria-hidden="true">↗</span></a></section>'''
  doc=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{esc(description)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f4f1e9"><title>{esc(title)} — Backstory Contenidos</title><link rel="icon" href="{asset('assets/5a561b07764b266c.png')}"><link rel="stylesheet" href="{asset('style.css')+'?v=2'}"><meta property="og:title" content="{esc(title)} — Backstory"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/og-backstory.svg"><link rel="alternate" hreflang="{'es' if en else 'en'}" href="{ORIGIN}/{other+routes.get(key,'casos/'+key+'/')}"><script src="{asset('site.js')}" defer></script></head><body><a class="skip" href="#main">{t('Saltar al contenido','Skip to content')}</a><div class="reading-progress" aria-hidden="true"></div><header class="nav"><a class="logo" href="{url('home')}" aria-label="Backstory — {t('Inicio','Home')}"><img src="{asset('assets/8064bf13856d4fb5.png')}" width="300" height="81" alt="Backstory Contenidos"></a><nav class="nav-links" aria-label="{t('Principal','Main')}">{nav}</nav><div class="nav-end"><a class="lang" href="{langlink}" lang="{'es' if en else 'en'}" aria-label="{t('Read in English','Leer en español')}">{'ES' if en else 'EN'} ↗</a><a class="contact-link" href="{url('contact')}">{t('Hablemos','Let’s talk')} ↗</a><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu">{t('Menú','Menu')} ☰</button></div></header><nav class="mobile-menu" id="mobile-menu" hidden aria-label="{t('Navegación móvil','Mobile navigation')}">{nav}<a href="{url('contact')}">{t('Contacto','Contact')}</a><a class="lang" href="{langlink}">{'Español' if en else 'English'} ↗</a></nav><main id="main">{body}{cta}</main><footer class="footer wrap"><div class="footer-top"><div><a href="{url('home')}"><img class="footer-logo" src="{asset('assets/33620dfbd0686df7.png')}" width="300" height="81" alt="Backstory Contenidos"></a><p>{t('Estrategia, creatividad y contenidos.','Strategy, creativity and content.')}</p></div><div><span class="eyebrow">{t('Empecemos por una conversación','It starts with a conversation')}</span><p><a href="mailto:info@backstory.com.ar">info@backstory.com.ar ↗</a><br>Buenos Aires, Argentina</p></div><div><span class="eyebrow">{t('Seguí la historia','Follow the story')}</span><p class="footer-links"><a href="https://www.instagram.com/somosbackstory/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.linkedin.com/company/backstory-contenidos/" target="_blank" rel="noopener">LinkedIn ↗</a></p></div></div><div class="footer-bottom"><span>© 2026 Backstory Contenidos · Letra Fértil SRL</span><button class="motion-toggle" aria-pressed="false" data-pause="{t('Pausar movimiento','Pause motion')}" data-resume="{t('Activar movimiento','Resume motion')}">{t('Pausar movimiento','Pause motion')}</button><span>{t('Hecho con intención. Desde Buenos Aires.','Made with intent. From Buenos Aires.')}</span><a href="{url('privacy')}">{t('Privacidad','Privacy')}</a></div></footer></body></html>'''
  p=DIST/current;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(doc)
 def card(c,n):return f'''<article class="work-card reveal" data-tags="{c['tags']}"><a href="@{c['slug']}@" aria-label="{t('Ver proyecto','View project')}: {esc(c['brand'])} — {esc(c['title'][ix])}"><div class="work-visual {'hoy' if c['slug']=='hoy-sabes' else 'slide' if c.get('slide') else ''}" style="--case-color:{c['color']}"><img src="@assets@/{c['image']}" alt="{esc(c['brand'])} — {esc(c['title'][ix])}" loading="lazy" width="1000" height="1000"><span class="work-open" aria-hidden="true">↗</span></div><div class="work-meta"><div><h3>{c['brand']}</h3><p>{c['title'][ix]}<br><span class="muted">{c['category'][ix]}</span></p></div><span class="work-number">/{n:02d}</span></div></a></article>'''
 def grid(selected,archive=False):return '<div class="work-grid '+('archive-grid' if archive else '')+'">'+''.join(card(c,i+1) for i,c in enumerate(selected))+'</div>'
 def caps():return '<div class="capability-list">'+''.join(f'''<a class="capability" href="@services@#cap-{i}"><span class="num">0{i+1}</span><h3>{s[0][ix]}</h3><p>{s[1][ix]}</p><span class="arrow" aria-hidden="true">↗</span></a>''' for i,s in enumerate(services))+'</div>'
 ticker=''.join(f'<span>{a}<b aria-hidden="true">✳</b></span>' for a in [t('Una buena historia cambia la conversación','A good story changes the conversation'),t('Estrategia con oficio narrativo','Strategy with a storyteller’s craft'),t('Ideas que llegan a producción','Ideas brought to life')]*2)

