 home=f'''<section class="v2-hero wrap"><div class="v2-kicker eyebrow"><span>Backstory Contenidos</span><span>Buenos Aires · {t('Mirada internacional','International perspective')}</span></div><h1>{t('Primero,<br><em>la historia.</em>','The story<br><em>comes first.</em>')}</h1><div class="v2-hero-bottom"><p>{t('Estrategia, creatividad y social media. Pensamos lo que una marca tiene para decir. Y lo hacemos vivir, todos los días.','Strategy, creativity and social media. We find what a brand has to say. And bring it to life, every day.')}</p><a class="text-link" href="#trabajo">{t('Ver el trabajo','Explore the work')} ↓</a></div></section><section class="v2-work wrap" id="trabajo"><div class="v2-section-label"><span class="eyebrow">01 / {t('El trabajo','The work')}</span><span>{t('Ideas que toman forma.','Ideas taking shape.')}</span></div>'''
 for i,c in enumerate(featured):
  home+=f'''<a class="v2-feature" href="@{c['slug']}@"><div class="v2-feature-image"><img src="@assets@/{c['image']}" alt="{esc(c['brand'])} — {esc(c['title'][ix])}" width="1600" height="900" loading="lazy"></div><div class="v2-feature-caption"><span class="eyebrow">0{i+1} / {c['category'][ix]}</span><h2>{c['brand']} <span aria-hidden="true">↗</span></h2><p>{c['lead'][ix]}</p></div></a>'''
 home+=f'''<a class="text-link v2-all" href="@work@">{t('Explorá todos los proyectos','Explore all projects')} ↗</a></section><section class="v2-social wrap" id="social-media"><div class="v2-section-label"><span class="eyebrow">02 / Social media</span><span>{t('Estrategia. Producción. Comunidad.','Strategy. Production. Community.')}</span></div><div class="v2-social-heading"><h2>{t('La marca.<br><em>Todos los días.</em>','The brand.<br><em>Every day.</em>')}</h2><p>{t('Hay historias que se cuentan en una campaña. Y marcas que construimos publicación a publicación. Planificamos, escribimos, diseñamos, producimos y sostenemos la conversación.','Some stories unfold in a campaign. Some brands are built post by post. We plan, write, design, produce and keep the conversation going.')}</p></div><div class="v2-social-grid"><a href="@history@" class="v2-social-piece"><img src="@assets@/0111c0d285182dc6.jpg" alt="{t('History: infografía editorial de El Socio','History: editorial infographic for The Profit')}" loading="lazy"><span>History <small>{t('Contenido editorial','Editorial content')} ↗</small></span></a><a href="@labyes@" class="v2-social-piece"><img src="@assets@/labyes-social-noviembre.png" alt="{t('Labyes: pieza para redes con un perro y su dueña jugando al aire libre','Labyes: social post showing a dog and its owner playing outdoors')}" width="1080" height="1080" loading="lazy"><span>Labyes <small>{t('Contenido para redes','Social content')} ↗</small></span></a></div><div class="v2-social-services"><div><h3>{t('Una voz','A voice')}</h3><p>{t('Estrategia editorial, tono y planificación.','Editorial strategy, tone and planning.')}</p></div><div><h3>{t('Muchos formatos','Many formats')}</h3><p>{t('Copy, diseño, video y animación para redes.','Copy, design, video and animation for social.')}</p></div><div><h3>{t('Una relación','A relationship')}</h3><p>{t('Publicación, comunidad y lectura de resultados.','Publishing, community and performance review.')}</p></div></div><p class="v2-social-note">{t('Entre las marcas con las que trabajamos en social media: History Channel y Turimar.','Our social media work includes History Channel and Turimar.')}</p><a class="text-link" href="@services@#cap-2">{t('Conocé cómo trabajamos social','Explore our social media services')} ↗</a></section><section class="section wrap v2-capabilities"><span class="eyebrow">03 / {t('Capacidades','Capabilities')}</span><h2 class="section-title">{t('Pensar. Crear.<br><span class="serif">Hacer.</span>','Think. Create.<br><span class="serif">Make.</span>')}</h2>{caps()}</section><section class="v2-origin wrap"><span class="eyebrow">04 / {t('El estudio','The studio')}</span><div><h2>{t('Venimos<br><em>del guion.</em>','Our roots<br><em>are in writing.</em>')}</h2><p>{t('El cine y la televisión nos enseñaron a construir una mirada, encontrar una tensión y sostener la atención. Llevamos ese oficio a la estrategia de las marcas, sus campañas y su comunicación cotidiana.','Film and television taught us to find a point of view, build tension and hold attention. We bring that craft to brand strategy, campaigns and everyday communication.')}</p><a class="text-link" href="@studio@">{t('La historia de Backstory','The Backstory story')} ↗</a></div></section><section class="v2-clients wrap"><span class="eyebrow">05 / {t('Marcas con las que trabajamos','Brands we have worked with')}</span><div class="v2-client-names">{''.join('<span>'+name+'</span>' for name in ['History Channel','AMC Networks','Pampers','Bagóvit','Pecom','GSK','Bureau Veritas','Havanna','Labyes','Turimar','Toyota Compañía Financiera','AICA · '+t('Estados Unidos','United States')])}</div></section>'''
 render('home',t('Primero, la historia','The story comes first'),home,t('Backstory: estrategia, creatividad y social media. Explorá nuestro trabajo para marcas.','Backstory: strategy, creativity and social media. Explore our work for brands.'))
 filters=[('all',t('Todo','All')),('entertainment',t('Entretenimiento','Entertainment')),('health',t('Salud y cuidado','Health & care')),('corporate','B2B'),('content',t('Contenidos','Content')),('digital','Digital'),('social','Social media')]
 work=f'''<section class="page-hero wrap"><span class="eyebrow">{t('Nuestro trabajo','Our work')} / Backstory</span><h1>{t('Historias.<br><span class="serif">En acción.</span>','Stories.<br><span class="serif">In action.</span>')}</h1><div class="page-intro"><p>{t('La mejor manera de conocernos es mirar lo que hacemos.','The best way to get to know us is through our work.')}</p><p class="small">{t('Una selección de nuestro archivo: entretenimiento, comunicación en salud, marcas de consumo y experiencias digitales.','A selection from our archive: entertainment, health communication, consumer brands and digital experiences.')}</p></div></section><section class="wrap section" style="padding-top:0"><div class="filters" aria-label="{t('Filtrar proyectos','Filter projects')}">{''.join(f'<button class="filter" data-filter="{value}" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,(value,label) in enumerate(filters))}<span class="filter-count" role="status" data-label="{t('proyectos','projects')}">{len(cases)} {t('proyectos','projects')}</span></div>{grid(cases,True)}</section>'''
 render('work',t('Trabajo','Work'),work,t('Explorá proyectos del archivo de Backstory: entretenimiento, salud, consumo y comunicación B2B.','Explore projects from the Backstory archive: entertainment, health, consumer brands and B2B communication.'))
 for i,c in enumerate(cases):
  nxt=cases[(i+1)%len(cases)]
  body=f'''<section class="page-hero case-hero wrap"><a class="eyebrow" href="@work@">← {t('Todos los proyectos','All projects')}</a><h1>{c['brand']}<br><span class="serif">{c['title'][ix]}</span></h1><div class="case-deck"><p class="lead">{c['lead'][ix]}</p><dl class="case-specs"><div><dt>{t('Marca','Brand')}</dt><dd>{c['brand']}</dd></div><div><dt>{t('Especialidad','Discipline')}</dt><dd>{c['category'][ix]}</dd></div></dl></div></section><section class="case-view" style="--case-color:{c['color']}"><div class="case-view-controls" aria-label="{t('Explorar el proyecto','Explore the project')}"><button data-view="piece" aria-pressed="true" aria-controls="case-piece">{t('La pieza','The piece')}</button><button data-view="story" aria-pressed="false" aria-controls="case-backstory">{t('Ver el backstory','See the backstory')} ↗</button></div><div class="case-image" id="case-piece" data-case-panel="piece"><div class="{'hoy-poster' if c['slug']=='hoy-sabes' else 'case-original'}"><img src="@assets@/{c['image']}" alt="{esc(c['brand'])}: {esc(c['title'][ix])}" width="1000" height="1000"></div></div><div class="case-backstage" id="case-backstory" data-case-panel="story" hidden><span class="eyebrow">{t('Detrás de la pieza','Behind the piece')}</span><h2>{c['lead'][ix]}</h2><p>{c['craft'][ix]}</p></div></section><section class="section wrap case-story"><span class="eyebrow">{t('El backstory','The backstory')}<br>/{i+1:02d}</span><div class="story-body"><h2>{t('El punto de partida','The starting point')}</h2><p>{c['context'][ix]}</p><h2>{t('La construcción','The craft')}</h2><p>{c['craft'][ix]}</p><h2>{t('El trabajo','The work')}</h2><ul>{''.join('<li>'+v+'</li>' for v in c['delivery'][ix])}</ul><p class="case-source">{t('Proyecto del archivo de Backstory.','A project from the Backstory archive.')} <a href="{c['source']}" target="_blank" rel="noopener">{c.get('source_label',[t('Ver referencia original','View original reference')]*2)[ix]} ↗</a></p></div></section><section class="next-case wrap"><span class="eyebrow">{t('Siguiente historia','Next story')}</span><a href="@{nxt['slug']}@">{nxt['brand']}<span aria-hidden="true">↗</span></a></section>'''
  render(c['slug'],c['brand']+' — '+c['title'][ix],body,c['lead'][ix])
 body=f'''<section class="page-hero wrap"><span class="eyebrow">{t('Capacidades','Capabilities')} / Backstory</span><h1>{t('Pensar.<br><span class="serif">Hacer que pase.</span>','Think it through.<br><span class="serif">Bring it to life.</span>')}</h1><div class="page-intro"><p>{t('El relato le da dirección al trabajo. El oficio lo lleva hasta el final.','The story gives the work direction. Craft takes it all the way.')}</p><p class="small">{t('Podemos trabajar sobre un desafío puntual o acompañar la comunicación de una marca en el tiempo. Empezamos por entender qué necesitás cambiar.','We can tackle a specific challenge or support a brand’s communication over time. We start by understanding what needs to change.')}</p></div></section><section class="wrap">'''
 for i,s in enumerate(services):body+=f'''<article class="service-detail" id="cap-{i}"><span class="eyebrow">0{i+1}</span><h2>{s[0][ix]}</h2><div><p>{s[2][ix]}</p><ul>{''.join('<li>'+v+'</li>' for v in s[3][ix])}</ul></div></article>'''
 steps=[(t('Escuchar','Listen'),t('Entender el negocio, la audiencia y la pregunta que hay que resolver.','Understand the business, the audience and the question to solve.')),(t('Encontrar','Find'),t('Definir la idea, el punto de vista y el lenguaje que va a sostenerla.','Define the idea, the point of view and the language that will sustain it.')),(t('Construir','Build'),t('Escribir, diseñar y producir, con revisiones claras en cada etapa.','Write, design and produce, with clear reviews at each stage.')),(t('Aprender','Learn'),t('Mirar la respuesta, revisar lo aprendido y mejorar la próxima entrega.','Review the response, capture what we learn and improve the next delivery.'))]
 body+=f'''</section><section class="section process wrap"><span class="eyebrow">{t('Cómo trabajamos','How we work')}</span><h2 class="section-title">{t('Un proceso.<br>Una conversación abierta.','A clear process.<br>An open conversation.')}</h2><div class="process-grid">{''.join(f'<article><span class="eyebrow">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(steps))}</div></section>'''
 render('services',t('Capacidades','Capabilities'),body,t('Estrategia de marca, contenido y campañas, social media y comunidades, web, guion y producción.','Brand strategy, content and campaigns, social media and communities, web, writing and production.'))
 studio=f'''<section class="page-hero wrap"><span class="eyebrow">{t('El estudio','The studio')} / Backstory</span><h1>{t('Tenemos<br><span class="serif">historia.</span>','We have<br><span class="serif">a backstory.</span>')}</h1><div class="page-intro"><p>{t('Somos un equipo que piensa la comunicación desde el oficio de contar.','We are a team that approaches communication through the craft of storytelling.')}</p><p class="small">{t('Estrategia, creatividad y producción. Con base en Buenos Aires y experiencia en comunicación para marcas y audiencias de la región.','Strategy, creativity and production. Based in Buenos Aires, with experience in communication for brands and audiences across the region.')}</p></div></section><section class="manifesto wrap"><span class="eyebrow">{t('Nuestro punto de vista','Our point of view')}</span><div><h2 class="statement">{t('Una historia empieza<br>con una <em>mirada.</em>','A story begins<br>with a <em>point of view.</em>')}</h2><p>{t('Nuestro origen está en el guion, el cine y la televisión. Aprendimos a escuchar cómo hablan las personas, a encontrar lo significativo en un detalle y a sostener la atención sin perder el sentido.','Our roots lie in writing, film and television. We learned to listen to how people speak, find meaning in a detail and hold attention without losing the point.')}</p><p>{t('Hoy aplicamos ese trabajo a las marcas: desde una definición estratégica hasta una campaña, una comunidad o una experiencia digital.','Today we bring that craft to brands: from a strategic definition to a campaign, a community or a digital experience.')}</p></div></section><section class="section wrap editorial"><span class="eyebrow">{t('Lo que nos mueve','What drives us')}</span><div class="editorial-text"><p>{t('Entender antes de proponer. Encontrar una idea que merezca el tiempo de quien la recibe.','Understand before proposing. Find an idea worthy of the audience’s time.')}</p><p class="serif">{t('Y cuidar el trabajo hasta el último detalle.','And care for the work down to its last detail.')}</p><p style="font:16px/1.7 Arial;letter-spacing:0">{t('Trabajamos cerca de nuestros clientes. Compartimos preguntas, ponemos las ideas a prueba y articulamos las capacidades que necesita cada proyecto. La relación también forma parte del resultado.','We work closely with our clients. We share questions, test ideas and bring together the skills each project needs. The relationship is part of the work, too.')}</p></div></section><section class="section wrap"><span class="eyebrow">{t('Equipo fundador','Founding team')}</span><h2 class="section-title">{t('La gente detrás<br>de la historia.','The people<br>behind the story.')}</h2><div class="people"><article class="person"><span class="eyebrow">01</span><h3>Bernabé Botte</h3><p>{t('Cofundador de Backstory Contenidos.','Co-founder of Backstory Contenidos.')}</p></article><article class="person"><span class="eyebrow">02</span><h3>Bernardo Gattó</h3><p>{t('Cofundador de Backstory Contenidos.','Co-founder of Backstory Contenidos.')}</p></article><article class="person"><span class="eyebrow">03</span><h3>Santiago Schere</h3><p>{t('Cofundador de Backstory Contenidos.','Co-founder of Backstory Contenidos.')}</p></article></div></section><section class="studio-teaser"><div class="studio-art" aria-hidden="true"><span class="giant">Aa.</span><span class="floating-label">{t('La próxima página','The next page')} ↗</span></div><div class="studio-copy"><span class="eyebrow">{t('Desarrollo original','Original development')}</span><h2>{t('Historias<br>por venir.','Stories<br>to come.')}</h2><p>{t('Además de la comunicación de marcas, trabajamos en el desarrollo de guiones, formatos y contenidos originales. La escritura es un espacio de exploración que alimenta nuestra mirada.','Alongside brand communication, we develop scripts, formats and original content. Writing is a space for exploration that keeps shaping our perspective.')}</p><a class="text-link" href="@contact@">{t('Conversemos sobre un proyecto','Let’s talk about a project')}<span aria-hidden="true">↗</span></a></div></section>'''
 render('studio',t('El estudio','The studio'),studio,t('Conocé el origen narrativo de Backstory y su manera de conectar estrategia, creatividad y producción.','Discover Backstory’s storytelling roots and its approach to strategy, creativity and production.'))
 contact=f'''<section class="page-hero wrap"><span class="eyebrow">{t('Empecemos','Let’s begin')} / Backstory</span><h1>{t('¿Hacemos<br><span class="serif">equipo?</span>','Let’s make<br><span class="serif">it happen.</span>')}</h1></section><section class="contact-layout wrap"><aside class="contact-aside"><h2>{t('Contanos qué tenés en mente.','Tell us what you have in mind.')}</h2><p>{t('Una marca que necesita encontrar su voz. Una campaña por lanzar. Una historia que merece ser contada.','A brand looking for its voice. A campaign to launch. A story worth telling.')}</p><a class="email" href="mailto:info@backstory.com.ar">info@backstory.com.ar</a><p>Buenos Aires, Argentina</p></aside><form class="brief-form"><div class="field-row"><div class="field"><label for="name">{t('Tu nombre *','Your name *')}</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="company">{t('Empresa','Company')}</label><input id="company" name="company" autocomplete="organization" maxlength="120"></div></div><div class="field"><label for="email">Email *</label><input type="email" id="email" name="email" autocomplete="email" required maxlength="200"></div><fieldset><legend>{t('¿En qué podemos ayudarte?','How can we help?')}</legend><div class="choices">{''.join(f'<label class="choice"><input type="checkbox" name="need" value="{esc(s[0][ix])}"><span>{s[0][ix]}</span></label>' for s in services)}</div></fieldset><div class="field"><label for="brief">{t('La primera idea *','The first idea *')}</label><textarea id="brief" name="brief" required maxlength="2500" placeholder="{t('Qué querés lograr, para quién y en qué momento.','What you want to achieve, who it’s for and your timing.')}"></textarea></div><p class="form-note">{t('Este formulario prepara un correo en tu dispositivo. Revisalo y envialo desde tu aplicación de email. No guarda tus datos ni los envía automáticamente.','This form prepares an email on your device. Review and send it from your email app. It does not store your details or send them automatically.')}</p><button class="pill" type="submit">{t('Preparar mi brief','Prepare my brief')} <span aria-hidden="true">↗</span></button><p class="form-status" role="status" tabindex="-1" hidden></p></form></section>'''
 render('contact',t('Hablemos','Let’s talk'),contact,t('Contanos tu próximo proyecto. Estrategia, creatividad y contenidos con Backstory.','Tell us about your next project. Strategy, creativity and content with Backstory.'))
 privacy=f'''<article class="privacy"><span class="eyebrow">Backstory Contenidos</span><h1>{t('Privacidad','Privacy')}</h1><p>{t('Esta versión del sitio no incorpora analítica publicitaria, píxeles de seguimiento ni formularios que guarden datos en una base de datos.','This version of the site does not include advertising analytics, tracking pixels or forms that store information in a database.')}</p><h2>{t('Contacto','Contact')}</h2><p>{t('El generador de brief funciona dentro de tu navegador. Cuando elegís abrir el correo, tu aplicación de email recibe el texto que escribiste. Vos decidís si lo enviás. También podés escribir directamente a','The brief builder runs in your browser. When you choose to open the email, your email app receives the text you entered. You decide whether to send it. You can also write directly to')} <a href="mailto:info@backstory.com.ar">info@backstory.com.ar</a>.</p><h2>{t('Enlaces externos y alojamiento','External links and hosting')}</h2><p>{t('Los enlaces a redes sociales y otras páginas abren servicios con sus propias políticas de privacidad. El proveedor de alojamiento puede procesar los datos técnicos necesarios para servir y proteger el sitio, y gestionar la entrega de esta versión de presentación.','Links to social networks and other pages open services with their own privacy policies. The hosting provider may process technical data needed to serve and secure the site, and to deliver this preview version.')}</p></article>'''
 render('privacy',t('Privacidad','Privacy'),privacy,t('Información sobre contacto y privacidad de esta versión del sitio.','Contact and privacy information for this version of the site.'))

